import xml.etree.ElementTree as ET
p='/conf/config.xml'
root=ET.parse(p).getroot()
def t(e, path):
    x=e.find(path)
    return (x.text or '').strip() if x is not None and x.text else ''
def flat(e):
    out=[]
    for x in e.iter():
        if x is e or x.tag in ('password','authserver','authorizedkeys','privatekey','secret','key'): continue
        if len(x)==0 and x.text and x.text.strip(): out.append('%s=%s' % (x.tag, x.text.strip()))
    return ','.join(out)
print('== saved interfaces ==')
ifs=root.find('interfaces')
if ifs is not None:
    for e in list(ifs):
        print(e.tag, flat(e))
print('== saved gateways ==')
gw=root.find('system/gateways')
if gw is not None:
    print(flat(gw))
print('== saved static routes ==')
sr=root.find('staticroutes')
if sr is not None:
    print(flat(sr))
print('== saved filter rules ==')
f=root.find('filter')
if f is not None:
    for i,e in enumerate(f.findall('rule'),1): print('rule%d %s' % (i, flat(e)))
print('== saved nat ==')
n=root.find('nat')
if n is not None:
    print('nat-root', flat(n))
    for i,e in enumerate(n.findall('.//rule'),1): print('rule%d %s' % (i, flat(e)))
